import React, { useState, useEffect } from "react";
import { useDispatch, useSelector } from "react-redux";
import { login } from "../Features/UserSlice";
import { useNavigate, Link } from "react-router-dom";
import "../Styles/Login.css";
import loginImg from "../Images/user-register.png";

const Login = () => {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");

  const dispatch = useDispatch();
  const navigate = useNavigate();

  const { user, isSuccess, isError } = useSelector((state) => state.users);

  useEffect(() => {
    if (isSuccess && user) {
      alert(
        `Welcome back, ${user.role === "company" ? "Company" : "Student"} ✅`
      );
      if (user.role === "company") {
        navigate("/company-profile");
      } else {
        navigate("/user-profile");
      }
    } else if (isError) {
      alert("❌ Invalid email or password");
    }
  }, [isSuccess, isError, user, navigate]);

  const handleLogin = () => {
    if (!email || !password) {
      alert("Please enter both email and password ❗");
      return;
    }

    const userData = { email, password };
    dispatch(login(userData));
  };

  return (
    <div className="login-page">
      <div className="login-container">
        {/* ✅ Left Side - Login Form */}
        <div className="login-form">
          <h1 className="login-title">
            Welcome <span className="accent">back</span>
          </h1>
          <p className="login-sub">Login to continue</p>

          <form>
            <label>Email</label>
            <input
              type="email"
              placeholder="you@example.com"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
            />

            <label>Password</label>
            <input
              type="password"
              placeholder="********"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
            />

            <button type="button" className="login-btn" onClick={handleLogin}>
              Login
            </button>

            <p className="login-text">
              Don’t have an account?{" "}
              <Link to="/user-register" className="login-link">
                Register now!
              </Link>
            </p>
          </form>
        </div>

        {/* ✅ Right Side - Image */}
        <div className="login-image">
          <img src={loginImg} alt="Login illustration" />
        </div>
      </div>
    </div>
  );
};

export default Login;
